function Send-Cdp($method,$params){$script:id++;$requestId=$script:id;$json=@{id=$requestId;method=$method;params=$params}|ConvertTo-Json -Depth 8 -Compress;$bytes=[Text.Encoding]::UTF8.GetBytes($json);$socket.SendAsync([ArraySegment[byte]]$bytes,[System.Net.WebSockets.WebSocketMessageType]::Text,$true,[Threading.CancellationToken]::None).GetAwaiter().GetResult();while($true){$stream=[IO.MemoryStream]::new();do{$buffer=New-Object byte[] 1048576;$result=$socket.ReceiveAsync([ArraySegment[byte]]$buffer,[Threading.CancellationToken]::None).GetAwaiter().GetResult();$stream.Write($buffer,0,$result.Count)}while(-not $result.EndOfMessage);$response=[Text.Encoding]::UTF8.GetString($stream.ToArray())|ConvertFrom-Json;if($response.id -eq $requestId){return $response}}}
function Eval($expression){Send-Cdp 'Runtime.evaluate' @{expression=$expression}|Out-Null;Start-Sleep -Milliseconds 120}
function Capture-Set($prefix){foreach($viewport in @(@{width=320;height=800},@{width=360;height=800},@{width=390;height=844},@{width=412;height=786},@{width=430;height=932})){Send-Cdp 'Emulation.setDeviceMetricsOverride' @{width=$viewport.width;height=$viewport.height;deviceScaleFactor=1;mobile=$true}|Out-Null;Start-Sleep -Milliseconds 180;Eval "document.querySelectorAll('.ait-panel-root,.ait-panel-toggle').forEach(e=>e.style.display='none')";$shot=Send-Cdp 'Page.captureScreenshot' @{format='png';fromSurface=$true;captureBeyondViewport=$false};[IO.File]::WriteAllBytes("C:\Users\user\Downloads\focus-result-$prefix-$($viewport.width)x$($viewport.height).png",[Convert]::FromBase64String($shot.result.data));$expression="JSON.stringify({overflow:document.documentElement.scrollWidth-document.documentElement.clientWidth,documentHeight:document.documentElement.scrollHeight,viewportHeight:innerHeight,items:document.querySelectorAll('.focus-result-item').length,selected:document.querySelectorAll('.focus-result-item.is-selected').length,target:document.querySelectorAll('.focus-result-item.is-target').length,focusable:document.querySelectorAll('.focus-result-item button,.focus-result-item[tabindex]').length,gridBottom:document.querySelector('.focus-result-grid').getBoundingClientRect().bottom,legendBottom:document.querySelector('.focus-result-legend').getBoundingClientRect().bottom,noteBottom:document.querySelector('.focus-result-note').getBoundingClientRect().bottom,buttonBottom:document.querySelector('.focus-result-action button').getBoundingClientRect().bottom})";$response=Send-Cdp 'Runtime.evaluate' @{expression=$expression;returnByValue=$true};Write-Output "$prefix-$($viewport.width): $($response.result.result.value)"}}
